            "eighthVectorResizingFromHalfUInt16 through GenericAnySourcePair<UInt8, UInt16>"
        )
        let aInputs = Inputs.conversions(SIMD<UInt16>.HalfVector.self, seed: 0x6295_002A_C665_20D0)
            .map(poisoningUpperBytes)
        for a in aInputs {
            let port = GenericAnySourcePair<UInt8, UInt16>.eighthVector(resizing: a)
            let reference = H.eighthVector(resizing: a)
            let definedBytes = SIMD<UInt16>.HalfVector.laneCount * MemoryLayout<UInt16>.stride
            let grownBytes = H.EighthVector.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                MemoryLayout<SIMD<UInt16>.HalfVector.Raw>.size
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

